                        border: `1px solid ${chatHealth?.ollama_ready ? '#4caf50' : '#f44336'}40`,
                        fontWeight: 600,
                      }}
                    />
                  </Box>
                </Box>
              </Grid>
              <Grid item xs={12} sm={4}>
                <Box sx={{
